    "blog_title": "Code review que enseña: feedback sin fricción",
    "blog_angle": "Un buen review acelera al equipo; uno malo solo genera tickets y resentimiento.",
    "blog_draft": "# Code review que enseña: feedback sin fricción\n\n## El problema\nLos reviews se vuelven cuellos de botella o teatro de nitpicks. El objetivo debería ser calidad compartida y aprendizaje, no demostrar superioridad.\n\n## Principios útiles\n1. **Intención primero**: ¿qué riesgo mitiga este comentario?\n2. **Preferir preguntas** cuando el contexto no es claro.\n3. **Separar bloqueantes de nice-to-have**.\n4. **Enseñar el porqué** con un ejemplo corto, no un tratado.\n5. **Aprobar con confianza** cuando el diff es seguro aunque no sea perfecto.\n\n## Anti-patrones\n- Revisar estilo que el linter ya cubre.\n- Pedir refactors masivos en un PR de bugfix.\n- Silencio durante días y luego un muro de comentarios.\n\n## Checklist práctico\n- ¿Hay tests o evidencia de verificación?\n- ¿Los nombres y límites son claros?\n- ¿Hay deuda nueva que deba quedar documentada?\n\n## Cierre\nEl review es un producto interno: mide latencia, claridad y cuánto mejora el siguiente PR del autor.",
    "x_copy": "Code review útil = riesgo mitigado + aprendizaje. Nitpick sin intención solo frena. #Engineering #CodeReview",
    "linkedin_copy": "Los mejores code reviews no demuestran quién sabe más: reducen riesgo y dejan al autor más fuerte para el próximo cambio. Separá bloqueantes de nice-to-have y explicá el porqué en una frase.",
    "instagram_task": "Carrusel: 5 reglas de code review que no duelen (bloqueante vs nice-to-have, preguntas primero, linter ≠ humano)."
  },
