    "blog_title": "Liderazgo técnico temprano: ownership sin micromanagement",
    "blog_angle": "El primer líder de ingeniería multiplica con claridad de ownership, no con control de cada commit.",
    "blog_draft": "# Liderazgo técnico temprano: ownership sin micromanagement\n\n## Contexto\nCuando un equipo crece, el cuello de botella deja de ser código y pasa a ser decisión: quién decide qué, con qué datos y en qué horizonte.\n\n## Lo que suele fallar\n- El líder revisa todo y se convierte en SPOF.\n- Nadie documenta trade-offs; cada decisión se reabre.\n- Prioridad = lo que grita más fuerte, no lo que mueve métricas.\n\n## Prácticas concretas\n1. **Ownership explícito** por servicio o dominio (con backup).\n2. **ADRs cortos** para decisiones reversibles vs irreversibles.\n3. **Cadencia de riesgo**: incidentes, deuda, capacidad.\n4. **Delegar outcomes**, no tareas sueltas.\n5. **Interfaces entre equipos** tan claras como las APIs.\n\n## Señales de salud\n- PRs fluyen sin el líder en cada uno.\n- Postmortems generan cambios, no solo slides.\n- El equipo puede explicar el “por qué” del roadmap.\n\n## Cierre\nLiderar ingeniería temprana es diseñar el sistema de trabajo: ownership, feedback loops y límites claros.",
    "x_copy": "Primer líder de eng ≠ revisar cada PR. Ownership claro + ADRs cortos + métricas de riesgo. #TechLeadership",
    "linkedin_copy": "El valor de un líder técnico temprano no es escribir más código: es sacar al equipo del modo “todo pasa por mí”. Ownership por dominio, decisiones documentadas y métricas de riesgo suelen rendir más que el micromanagement.",
    "instagram_task": "Post: 4 señales de que el liderazgo técnico está escalando (ownership, ADRs, postmortems con acción, PRs sin SPOF)."
  },
